"""Generation of ``viewpie.yaml`` configuration documents.

The produced YAML follows the schema of the original viewpie project
(https://github.com/snoack/viewpie): top-level keys ``display``, ``feeds``,
``panels`` and ``defaults``. Layout grids are emitted as YAML block
scalars so that they remain human-editable.
"""

from __future__ import annotations

import logging
from typing import Optional

import yaml

from .models import Block, Camera, DisplaySettings, Panel
from .parser import render_matrix

logger = logging.getLogger(__name__)

_HEADER = (
    "# Generated by viewpie-layout-engine\n"
    "# SPDX-License-Identifier: GPL-3.0-or-later\n"
)


class _Dumper(yaml.SafeDumper):
    """SafeDumper subclass that prefers block style for multi-line strings."""

    def ignore_aliases(self, data: object) -> bool:  # noqa: D102
        return True


def _str_presenter(dumper: _Dumper, data: str) -> yaml.Node:
    """Emit strings containing newlines as literal block scalars."""
    if "\n" in data:
        return dumper.represent_scalar("tag:yaml.org,2002:str", data, style="|")
    return dumper.represent_scalar("tag:yaml.org,2002:str", data)


_Dumper.add_representer(str, _str_presenter)


def _dump(data: dict) -> str:
    """Serialize a dict with the custom dumper."""
    return yaml.dump(data, Dumper=_Dumper, sort_keys=False, default_flow_style=False, width=1000)


def camera_to_feed(camera: Camera) -> dict:
    """Convert a :class:`Camera` model into a viewpie feed entry."""
    feed: dict = {"url": camera.url}
    if camera.fullscreen_url:
        feed["fullscreen_url"] = camera.fullscreen_url
    return feed


def blocks_to_layout_text(blocks: list[Block], size: int) -> str:
    """Rebuild layout text from explicit rectangular blocks.

    Args:
        blocks: Non-overlapping rectangles inside an N×N grid.
        size: Grid dimension N.

    Returns:
        Canonical layout text; uncovered cells are ``.``.
    """
    grid = [["."] * size for _ in range(size)]
    for b in blocks:
        for y in range(b.top, b.bottom + 1):
            for x in range(b.left, b.right + 1):
                grid[y][x] = b.label
    return render_matrix(grid)


def generate_panel_yaml(panel: Panel, blocks: Optional[list[Block]] = None) -> str:
    """Generate the YAML fragment describing a single panel.

    Args:
        panel: Panel model (id, name, layout text, viewports…).
        blocks: Optional explicit blocks; when given and the panel has no
            layout text, the layout is rebuilt from them.

    Returns:
        YAML string with one mapping under key ``panel``.
    """
    layout = panel.layout
    if not layout.strip() and blocks:
        size = max((b.bottom + 1) for b in blocks)
        size = max(size, 3)
        layout = blocks_to_layout_text(blocks, size)

    data: dict = {
        "id": panel.id,
        "name": panel.name,
        "layout": layout,
        "slots": [vp.slot for vp in panel.viewports],
    }
    if panel.spacing is not None:
        data["spacing"] = panel.spacing
    if panel.background is not None:
        data["background"] = panel.background

    viewports = []
    for vp in panel.viewports:
        entry: dict = {"slot": vp.slot, "feeds": list(vp.feeds)}
        if vp.rotation_interval is not None:
            entry["rotation_interval"] = vp.rotation_interval
        viewports.append(entry)
    if viewports:
        data["viewports"] = viewports

    return _dump({"panel": data})


def generate_viewpie_yaml(
    feeds: dict[str, Camera],
    panels: list[Panel],
    settings: DisplaySettings,
    active_panel: str,
) -> str:
    """Generate a complete ``/etc/viewpie/viewpie.yaml`` document.

    Args:
        feeds: Registry mapping camera name → Camera model.
        panels: All configured panels (at least one required).
        settings: Global display settings.
        active_panel: Id of the panel to show on startup.

    Returns:
        Full YAML text starting with a header comment.

    Raises:
        ValueError: If ``panels`` is empty or ``active_panel`` is unknown.
    """
    if not panels:
        raise ValueError("at least one panel is required")
    if active_panel not in {p.id for p in panels}:
        raise ValueError(f"active panel '{active_panel}' is not defined")

    used_feeds: set[str] = set()
    yaml_panels: list[dict] = []
    for panel in panels:
        pdata: dict = {"id": panel.id, "name": panel.name, "layout": panel.layout}
        if panel.spacing is not None:
            pdata["spacing"] = panel.spacing
        if panel.background is not None:
            pdata["background"] = panel.background
        vps: list[dict] = []
        for vp in panel.viewports:
            used_feeds.update(vp.feeds)
            entry: dict = {"slot": vp.slot, "feeds": list(vp.feeds)}
            if vp.rotation_interval is not None:
                entry["rotation_interval"] = vp.rotation_interval
            vps.append(entry)
        if vps:
            pdata["viewports"] = vps
        yaml_panels.append(pdata)

    feeds_map: dict[str, dict] = {}
    for name in sorted(used_feeds | {c.name for c in feeds.values()}):
        cam = feeds.get(name)
        if cam is None:
            continue
        feeds_map[name] = camera_to_feed(cam)

    document = {
        "display": {
            "spacing": settings.spacing,
            "pause_off_screen": settings.pause_off_screen,
            "background": settings.background,
        },
        "feeds": feeds_map,
        "panels": yaml_panels,
        "defaults": {
            "panel": active_panel,
            "rotation_interval": settings.rotation_interval,
            "fullscreen_timeout": settings.fullscreen_timeout,
        },
    }

    text = _HEADER + _dump(document)
    logger.debug("Generated viewpie.yaml with %d feeds, %d panels",
                 len(feeds_map), len(yaml_panels))
    return text
